    def add_sewage_treat_plant_node(self, plant_id: Any, *, source: str = "") -> str:
        plant_key = safe_key(plant_id)
        if not plant_key:
            return ""
        node = self.add_node("sewage_treat_plant", plant_key, name=plant_key, source=source)
